"""App interactiva del Trabajo Final: brecha firme del SIN y expansión de mínimo costo (Shiny for Python).

Cambia los supuestos del MILP de la Fase 5 (escenario, retrasos, tope solar, cupo de diésel y
penalidad) y compara construir con racionar en 2029-2030 según la probabilidad de El Niño.

Uso (carpeta del proyecto):
    shiny run app/app.py
El MILP se resuelve en vivo con src/suficiencia/expansion.py; sin src/ (por ejemplo, en el sitio
estático de shinylive) la app lee la grilla de app/datos/, que escribe python app/precalcular.py.
"""

import sys
from pathlib import Path

import pandas as pd
from plotly.offline import get_plotlyjs_version
from shiny import App, reactive, render, ui

sys.path.insert(0, str(Path(__file__).resolve().parent))
import figuras as fg  # noqa: E402
import motor  # noqa: E402
from figuras import num, pct  # noqa: E402

M = motor.crear()
CTX = M.contexto
ESC = CTX["escenarios"]
ULTIMO = CTX["periodos"][-1]
NINO = {r["periodo"]: r for r in CTX["nino"]}[ULTIMO]
NOMBRES_TEC = CTX["nombres_tecnologia"]
DEMANDA = {"media": "demanda media", "alta": "demanda alta"}

TOPES = {CTX["topes_solar"]["observado"]: "récord observado en XM",
         CTX["topes_solar"]["referencia_pieg"]: "PIEG 2025-2039, referencia",
         CTX["topes_solar"]["maximo_pieg"]: "PIEG 2025-2039, máximo"}
DIESEL = {CTX["cupos_diesel"][0]: "caso central", CTX["cupos_diesel"][1]: "supuesto sin fuente"}
PENALIDADES = {"costo_racionamiento_upme": "Costo de racionamiento de la UPME, primer tramo",
               "precio_escasez_superior": "Precio de escasez superior",
               "precio_escasez_inferior": "Precio de escasez inferior"}


MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre",
         "diciembre"]


def mes(texto: str) -> str:
    """'2026-10' -> 'octubre de 2026'."""
    anio, m = texto.split("-")[:2]
    return f"{MESES[int(m) - 1]} de {anio}"


def nombre_caso(demanda: str, retrasos: bool) -> str | None:
    """Escenario del trabajo que corresponde a una demanda y un supuesto de retrasos (o None)."""
    return next((e["nombre"] for e in ESC.values() if e["demanda"] == demanda and e["retrasos"] == retrasos), None)


def descripcion(demanda: str, retrasos: bool) -> str:
    return f"{DEMANDA[demanda]}, {'con' if retrasos else 'sin'} retrasos"


# ---------------------------------------------------------------------------------------------
# Interfaz
# ---------------------------------------------------------------------------------------------

def caja(titulo: str, valor: str, detalle: str):
    return ui.value_box(titulo, ui.output_text(valor), ui.div(ui.output_text(detalle), class_="vb-detalle"), theme="light")


barra = ui.sidebar(
    ui.input_radio_buttons("escenario", "Escenario", {k: e["nombre"] for k, e in ESC.items()}, selected="base", inline=True),
    ui.input_switch("retrasos", "Retrasos de los proyectos con OEF", value=ESC["base"]["retrasos"]),
    ui.output_ui("nota_escenario"),
    ui.input_select("tope", "Tope de construcción solar (MW por año)",
                    {str(v): f"{num(v)} ({t})" for v, t in TOPES.items()}),
    ui.input_radio_buttons("diesel", "Cupo de diésel nuevo", {str(v): f"{num(v)} MW ({t})" for v, t in DIESEL.items()}),
    ui.input_select("penalidad", "Penalidad de la energía no cubierta",
                    {k: f"{PENALIDADES[k]} ({num(CTX['penalidades'][k]['usd_mwh'])} USD/MWh)" for k in CTX["penalidades"]},
                    selected=CTX["criterio_central"]),
    ui.hr(class_="my-1"),
    ui.tags.strong(f"Construir o racionar, {ULTIMO}"),
    ui.input_slider("p_nino", f"P(El Niño en {ULTIMO})", 0, 100, round(NINO["probabilidad"] * 100), step=1, post="%"),
    ui.tags.small(f"Por análogos: {pct(NINO['probabilidad'], 0)} ({NINO['con_nino']} de {NINO['analogos']} episodios "
                  f"desde 1950 con 6 meses o más de El Niño en el tramo equivalente). Tasa base: "
                  f"{pct(NINO['tasa_base'], 0)}.", class_="text-muted"),
    ui.input_slider("p_racionar", "P(racionar | El Niño)", 0, 100, 50, step=1, post="%"),
    ui.tags.small("Supuesto sin cifra publicada: muévalo para ver dónde cambia la respuesta.", class_="text-muted"),
    width=330, title="Supuestos", open="always",
)

estilos = ui.tags.style("""
    .bslib-value-box .value-box-title { font-size: .85rem; margin-bottom: .2rem; }
    .bslib-value-box .value-box-value { font-size: 1.35rem; font-weight: 600; line-height: 1.2; white-space: nowrap; }
    .bslib-value-box .vb-detalle { font-size: .78rem; line-height: 1.3; }
    table.tabla { font-size: .85rem; }
    table.tabla td, table.tabla th { text-align: right; padding: 2px 10px; }
    table.tabla td:first-child, table.tabla th:first-child { text-align: left; white-space: nowrap; }
    .nota { font-size: .85rem; color: #52514e; }
""")

app_ui = ui.page_sidebar(
    barra,
    ui.head_content(ui.tags.script(src=f"https://cdn.plot.ly/plotly-{get_plotlyjs_version()}.min.js", charset="utf-8"),
                    estilos),
    ui.output_ui("encabezado"),
    ui.layout_column_wrap(
        caja(f"Brecha firme {ULTIMO}", "vb_brecha", "vb_brecha_det"),
        caja(f"MW nuevos en {ULTIMO}", "vb_mw", "vb_mw_det"),
        caja("Costo de construir (valor presente)", "vb_costo", "vb_costo_det"),
        caja("Energía sin cubrir, 2026-2027 a 2029-2030", "vb_sin", "vb_sin_det"),
        ui.output_ui("vb_decision"),
        width="165px", fill=False, heights_equal="row",
    ),
    ui.navset_card_underline(
        ui.nav_panel("Brecha y cobertura", ui.output_ui("fig_cobertura"), ui.output_table("tabla_periodos"),
                     ui.p("La brecha firme es la de la Fase 4 (demanda menos oferta firme) y solo cambia con el escenario "
                          "y los retrasos. Las barras son la energía firme de los bloques que construye el MILP; la parte "
                          "rayada es la que ningún bloque alcanza a cubrir y paga la penalidad.", class_="nota")),
        ui.nav_panel("Portafolio", ui.output_ui("fig_portafolio"), ui.output_table("tabla_portafolio"),
                     ui.output_ui("nota_portafolio")),
        ui.nav_panel("Construir o racionar", ui.output_ui("texto_decision"),
                     ui.layout_columns(ui.output_ui("fig_plano"), ui.div(ui.output_ui("fig_costos"), ui.output_ui("nota_costos")),
                                      col_widths=[7, 5]),
                     ui.output_table("tabla_construir"),
                     ui.p("Probabilidad de equilibrio = costo anual de los bloques que operan en el período / costo de "
                          "racionar toda la brecha con los cuatro tramos del costo de racionamiento de la UPME. Solo existe "
                          "en los períodos que los bloques cubren por completo. Umbral de P(racionar | El Niño) = equilibrio "
                          "/ P(El Niño por análogos).", class_="nota")),
        ui.nav_panel("Cómo leerla", ui.output_ui("como_leerla")),
    ),
    title="Suficiencia del SIN 2027-2030: brecha firme y expansión de mínimo costo",
    window_title="Suficiencia del SIN",
    fillable=False,
)


# ---------------------------------------------------------------------------------------------
# Servidor
# ---------------------------------------------------------------------------------------------

def server(input, output, session):

    @reactive.effect
    @reactive.event(input.escenario, ignore_init=True)
    def _retrasos_del_escenario():
        ui.update_switch("retrasos", value=ESC[input.escenario()]["retrasos"])

    @reactive.calc
    def demanda() -> str:
        return ESC[input.escenario()]["demanda"]

    @reactive.calc
    def caso() -> dict:
        return M.caso(demanda(), bool(input.retrasos()), int(input.tope()), int(input.diesel()), input.penalidad())

    @reactive.calc
    def fila() -> pd.Series:
        cr = caso()["construir"]
        return cr[cr["periodo"] == ULTIMO].iloc[0]

    @reactive.calc
    def p_nino() -> float:
        return input.p_nino() / 100

    @reactive.calc
    def p_racionar() -> float:
        return p_nino() * input.p_racionar() / 100

    @reactive.calc
    def titulo_caso() -> str:
        nombre = nombre_caso(demanda(), bool(input.retrasos()))
        return f"{nombre or 'Combinación propia'}: {descripcion(demanda(), bool(input.retrasos()))}"

    # --- Encabezado y nota del escenario ---------------------------------------------------------

    @render.ui
    def nota_escenario():
        d, r = demanda(), bool(input.retrasos())
        nombre = nombre_caso(d, r)
        if nombre == ESC[input.escenario()]["nombre"]:
            return ui.tags.small(f"{nombre}: {descripcion(d, r)}.", class_="text-muted")
        if nombre:
            return ui.tags.small(f"Con este cambio el caso equivale al escenario {nombre} ({descripcion(d, r)}).",
                                 class_="text-warning")
        return ui.tags.small(f"{descripcion(d, r).capitalize()}: no es uno de los tres escenarios del trabajo.",
                             class_="text-warning")

    @render.ui
    def encabezado():
        pen = CTX["penalidades"][input.penalidad()]
        return ui.p(ui.tags.strong(titulo_caso()),
                    f" · tope solar {num(int(input.tope()))} MW/año · diésel {num(int(input.diesel()))} MW · penalidad "
                    f"{num(pen['usd_mwh'])} USD/MWh · motor: {M.nombre}", class_="nota mb-1")

    # --- Cajas de valores ------------------------------------------------------------------------

    @render.text
    def vb_brecha():
        return f"{num(fila()['brecha_firme_gwh'])} GWh"

    @render.text
    def vb_brecha_det():
        per = caso()["periodos"]
        k = per["brecha_firme_gwh"].idxmax()
        return (f"{pct(fila()['brecha_pct'])} de la demanda; máximo {num(per.at[k, 'brecha_firme_gwh'])} GWh "
                f"en {per.at[k, 'periodo']}")

    @render.text
    def vb_mw():
        return f"{num(caso()['resumen']['mw_nuevos'])} MW"

    @render.text
    def vb_mw_det():
        r = caso()["resumen"]
        mw = {t: r.get(f"mw_{t}", 0) for t in CTX["colores"]["tecnologia"]}
        partes = [f"{num(v)} {NOMBRES_TEC[t].lower()}" for t, v in sorted(mw.items(), key=lambda x: -x[1]) if v > 0]
        return " · ".join(partes) or "El MILP no construye nada"

    @render.text
    def vb_costo():
        return f"{num(caso()['resumen']['costo_bloques_vp_musd'])} MUSD"

    @render.text
    def vb_costo_det():
        r = caso()["resumen"]
        return (f"USD de {CTX['anio_usd']}, tasa real {pct(CTX['tasa_descuento'], 0)}; "
                f"{num(r['costo_bloques_vp_billones_cop'], 2)} billones de COP")

    @render.text
    def vb_sin():
        return f"{num(caso()['resumen']['no_cubierta_gwh'])} GWh"

    @render.text
    def vb_sin_det():
        per = caso()["periodos"]
        con = per.loc[per["no_cubierta_gwh"] >= 1, "periodo"].tolist()
        donde = f"en {', '.join(con)}" if con else "toda la brecha queda cubierta"
        return f"{donde}; penalidad en valor presente: {num(caso()['resumen']['costo_penalidad_vp_musd'])} MUSD"

    @render.ui
    def vb_decision():
        eq = fila()["probabilidad_equilibrio"]
        if pd.isna(eq):
            valor, detalle, tema = "Sin equilibrio", "El MILP no cubre toda la brecha del período", "light"
        elif p_racionar() > eq:
            valor, detalle, tema = "Construir", f"P(racionar) {pct(p_racionar())} > equilibrio {pct(eq)}", "primary"
        else:
            valor, detalle, tema = "Racionar", f"P(racionar) {pct(p_racionar())} ≤ equilibrio {pct(eq)}", "warning"
        return ui.value_box(f"{ULTIMO}: ¿construir o racionar?", valor, ui.div(detalle, class_="vb-detalle"), theme=tema)

    # --- Brecha y cobertura ----------------------------------------------------------------------

    @render.ui
    def fig_cobertura():
        r = caso()
        return ui.HTML(fg.html(fg.cobertura(r["periodos"], r["portafolio"], CTX, f"¿Con qué se cierra la brecha? {titulo_caso()}")))

    @render.table(index=False, classes="table table-sm tabla w-auto")
    def tabla_periodos():
        p = caso()["periodos"]
        return pd.DataFrame({
            "Período": p["periodo"],
            "Demanda (GWh)": p["demanda_gwh"].map(num),
            "Brecha firme (GWh)": p["brecha_firme_gwh"].map(num),
            "Brecha (% demanda)": (p["brecha_firme_gwh"] / p["demanda_gwh"]).map(pct),
            "Firme nueva (GWh)": p["firme_nueva_gwh"].map(num),
            "Sin cubrir (GWh)": p["no_cubierta_gwh"].map(num),
            "Bloques (MUSD/año)": p["costo_bloques_musd"].map(num),
            "Penalidad (MUSD)": p["costo_penalidad_musd"].map(num),
            "Solar con OEF (MW)": p["solar_comprometida_mw"].map(num),
            "Tope solar libre (MW)": p["tope_solar_libre_mw"].map(num),
            "Solar nueva (MW)": p["solar_nueva_mw"].map(num),
        })

    # --- Portafolio ------------------------------------------------------------------------------

    @render.ui
    def fig_portafolio():
        return ui.HTML(fg.html(fg.portafolio(caso()["portafolio"], CTX,
                                             f"MW nuevos en operación por tecnología: {titulo_caso()}")))

    @render.table(index=False, classes="table table-sm tabla w-auto")
    def tabla_portafolio():
        p = caso()["portafolio"]
        t = p.pivot_table(index="tecnologia", columns="periodo", values="mw_nuevos", aggfunc="sum", sort=False)
        t = t.reindex(index=[k for k in CTX["colores"]["tecnologia"] if k in t.index], columns=CTX["periodos"])
        t["Total en " + ULTIMO] = t.sum(axis=1)
        t = t[t.sum(axis=1) > 0]
        if t.empty:
            return pd.DataFrame({"MW nuevos": ["El MILP no construye nada con estos supuestos"]})
        t.loc["Total"] = t.sum()
        salida = t.map(num)
        salida.insert(0, "MW que entran en cada período", [NOMBRES_TEC.get(i, i) for i in t.index])
        return salida

    @render.ui
    def nota_portafolio():
        r = caso()["resumen"]
        return ui.p(f"Costo de los bloques en valor presente: {num(r['costo_bloques_vp_musd'])} MUSD; con la penalidad de "
                    f"la energía no cubierta, el costo total es {num(r['costo_total_vp_musd'])} MUSD "
                    f"({num(r['costo_total_vp_billones_cop'], 2)} billones de COP). Brecha entre el MILP y su relajación "
                    f"lineal: {pct(r['brecha_entera_pct'], 2)}.", class_="nota")

    # --- Construir o racionar --------------------------------------------------------------------

    @render.ui
    def texto_decision():
        f, pn, pr = fila(), p_nino(), p_racionar()
        eq = f["probabilidad_equilibrio"]
        base = (f"En {ULTIMO}, cubrir la brecha de {num(f['brecha_firme_gwh'])} GWh cuesta {num(f['costo_cubrir_musd'])} MUSD "
                f"({num(f['costo_cubrir_usd_mwh'])} USD por MWh firme) y racionarla toda, {num(f['racionar_brecha_musd'])} MUSD "
                f"({num(f['racionar_usd_mwh'])} USD/MWh). ")
        if pd.isna(eq):
            return ui.p(base + "Con estos supuestos el MILP deja parte de la brecha sin cubrir, así que no hay probabilidad de "
                        "equilibrio: la penalidad elegida hace que racionar salga más barato que construir.", class_="mb-2")
        umbral = eq / pn if pn > 0 else float("nan")
        decision = "construir conviene" if pr > eq else "racionar sale más barato en valor esperado"
        texto = (base + f"La probabilidad de equilibrio es {pct(eq)}. Con P(El Niño) = {pct(pn, 0)} y P(racionar | El Niño) = "
                 f"{pct(input.p_racionar() / 100, 0)}, la probabilidad de racionar es {pct(pr)}: {decision}. ")
        if pn > 0:
            texto += (f"Con esa P(El Niño), construir conviene si P(racionar | El Niño) pasa de {pct(umbral)}."
                      if umbral <= 1 else "Con esa P(El Niño), ni racionando seguro en un año de El Niño conviene construir.")
        return ui.p(texto, class_="mb-2")

    @render.ui
    def fig_plano():
        return ui.HTML(fg.html(fg.plano_probabilidades(fila()["probabilidad_equilibrio"], p_nino(), input.p_racionar() / 100,
                                                       NINO["probabilidad"], CTX, f"¿Construir o racionar en {ULTIMO}?")))

    @render.ui
    def fig_costos():
        return ui.HTML(fg.html(fg.costos_2029(fila(), p_racionar(), CTX, f"Costos de {ULTIMO} (MUSD)")))

    @render.ui
    def nota_costos():
        f = fila()
        return ui.p(f"Construir: costo anual de los bloques que operan en {ULTIMO} (inversión anualizada, O&M y combustible "
                    f"esperado). Racionar: la brecha entera con los tramos del costo de racionamiento de la UPME, y su valor "
                    f"esperado con P(racionar) = {pct(p_racionar())}. La barra de construir es menor que la de racionar en "
                    f"valor esperado si P(racionar) supera el equilibrio ({pct(f['probabilidad_equilibrio'])}).", class_="nota")

    @render.table(index=False, classes="table table-sm tabla w-auto")
    def tabla_construir():
        c = caso()["construir"]
        return pd.DataFrame({
            "Período": c["periodo"],
            "Brecha (GWh)": c["brecha_firme_gwh"].map(num),
            "Sin cubrir (GWh)": c["no_cubierta_gwh"].map(num),
            "Cubrir (MUSD)": c["costo_cubrir_musd"].map(num),
            "Cubrir (USD/MWh)": c["costo_cubrir_usd_mwh"].map(num),
            "Racionar (MUSD)": c["racionar_brecha_musd"].map(num),
            "Racionar (USD/MWh)": c["racionar_usd_mwh"].map(num),
            "Equilibrio": c["probabilidad_equilibrio"].map(pct),
            "P(El Niño), análogos": c["probabilidad_nino"].map(lambda v: pct(v, 0)),
            "Umbral P(racionar | El Niño)": c["racionar_dado_nino_equilibrio"].map(pct),
        })

    # --- Cómo leerla -----------------------------------------------------------------------------

    @render.ui
    def como_leerla():
        rt, mon = CTX["retrasos"], CTX["moneda"]
        tramos = CTX["racionamiento"]
        return ui.markdown(f"""
**Qué resuelve.** Con cada combinación de supuestos la app corre el MILP de la Fase 5 (`expansion.correr()`): cuántos
bloques de cada tecnología entran en cada período del Cargo por Confiabilidad para cerrar la brecha de energía firme de
la Fase 4 al menor costo, y cuánta energía queda sin cubrir porque nada alcanza a llegar a tiempo. Esa energía paga la
penalidad elegida. Demanda: {CTX['demanda']['fuente']} (definición {CTX['definicion']}).

**Controles del MILP.**
- *Escenario.* Base y optimista usan la demanda media de la UPME; estrés, el límite superior del intervalo del 68%. Al
  cambiar de escenario, el interruptor de retrasos toma el valor del escenario; después se puede cambiar por separado
  (por ejemplo, demanda alta sin retrasos, que no es ninguno de los tres escenarios).
- *Retrasos.* Con retrasos, la OEF de los proyectos nuevos entra como entraron las plantas de la subasta de 2019:
  {pct(rt['a_tiempo'], 0)} a tiempo, {pct(rt['tarde'], 0)} {rt['periodos_retraso']} períodos tarde y el resto no entra. Sin
  retrasos, toda entra a tiempo. Cambia la brecha y los MW solares con OEF que ocupan el tope solar.
- *Tope solar.* MW solares que pueden entrar en un período, contando los proyectos con OEF y los bloques nuevos.
- *Cupo de diésel.* MW de motores diésel nuevos; el caso central no tiene (sin fuente para el cupo).
- *Penalidad.* USD de {CTX['anio_usd']} por MWh sin cubrir, con la TRM ({num(mon['trm'], 0)} COP/USD) y el CPI de
  {mes(mon['mes'])}. El caso central usa el primer tramo del costo de racionamiento de la UPME, el más barato.

**Salidas.** Costos en millones de USD de {CTX['anio_usd']} (MUSD); valor presente con tasa real de
{pct(CTX['tasa_descuento'], 0)} (PIEG 2025-2039), descontado a {CTX['periodos'][0]}. El costo de construir es el de los
bloques (inversión anualizada, O&M y combustible esperado) en el horizonte; la energía sin cubrir suma los cuatro períodos.

**Construir o racionar.** La brecha firme no es energía racionada: es lo que el parque no puede garantizar en un año seco.
La probabilidad de equilibrio es el costo anual de cubrir la brecha dividido por el costo de racionarla toda, con los cuatro
tramos del costo de racionamiento de la UPME ({', '.join(f'{num(u)}' for _, _, u in tramos)} USD/MWh). Construir conviene si
la probabilidad de racionar es mayor. Si el racionamiento solo llega con El Niño, esa probabilidad es
P(El Niño) × P(racionar | El Niño): ninguna de las dos entra al MILP. La P(El Niño) inicial es la de los análogos: cada
episodio de El Niño desde 1950 se alinea con el que empezó en {mes(NINO['inicio_episodio'])} y se cuenta si el tramo equivalente
a {ULTIMO} tuvo 6 meses o más de El Niño ({NINO['con_nino']} de {NINO['analogos']}). P(racionar | El Niño) no tiene cifra
publicada.

**Motor.** {M.nombre}. {'Cada caso se resuelve al cambiar un control (unos 0,05 s) y queda en memoria.' if M.vivo else
'Los 72 casos (2 demandas × 2 retrasos × 3 topes × 2 cupos × 3 penalidades) se calcularon con el MILP en vivo y python app/precalcular.py comprueba que la grilla dé las mismas cifras.'}
""")


app = App(app_ui, server)
